/**
 * E7 — public event catalog. THE source of truth for:
 *
 * - what `GET /events/catalog` serves (types, descriptions, required scope,
 *   JSON Schema of `data`, a full example of the POSTed body);
 * - which types an endpoint may subscribe to (WebhooksService);
 * - docs/developers/catalogo-de-eventos.md (generated by
 *   `scripts/generate-events-catalog.mjs`, checked by catalog.spec.ts).
 *
 * Public names are stable and versioned per type (`.v1`). A breaking change
 * to `data` is a new type (`.v2`) published next to the old one for a while,
 * never an edit of an existing schema. Adding an optional field is not
 * breaking.
 *
 * The `data` views reuse the Data API v1 projections (views.ts), with the
 * same PII rules: contact fields only with
 * `kernel.service.persons.contact.read`, never internal notes.
 */

export type JsonSchema = Record<string, unknown>;

export type EventDefinition = {
  /** Public type, e.g. "membership.activated.v1". */
  type: string;
  /** Type without its version, e.g. "membership.activated". */
  name: string;
  version: number;
  /** Short Spanish label for the console. */
  title: string;
  /** Spanish description: when it happens. */
  description: string;
  /** Service scope the app needs to receive it (null: every app). */
  scope: string | null;
  /** JSON Schema (draft 2020-12) of `data`. */
  schema: JsonSchema;
  /** Example of `data`. */
  example: Record<string, unknown>;
};

const nullableString = { type: ["string", "null"] };
const nullableDateTime = { type: ["string", "null"], format: "date-time" };

const MEMBERSHIP_STATUS = [
  "PENDING",
  "ACTIVE",
  "ON_LEAVE",
  "INACTIVE",
  "GRADUATED",
  "TRANSFERRED",
];

