/** Sent by "Enviar prueba"; not subscribable. */
export const PING_EVENT_TYPE = "ping.v1";

export const EVENT_TYPES = EVENT_CATALOG.map((event) => event.type);

/** Types an endpoint may subscribe to. */
export const SUBSCRIBABLE_EVENT_TYPES = EVENT_TYPES.filter(
  (type) => type !== PING_EVENT_TYPE,
);

export function eventDefinition(type: string): EventDefinition | undefined {
  return EVENT_CATALOG.find((event) => event.type === type);
}

/** JSON Schema of the POSTed body (the same for every type). */
export const ENVELOPE_SCHEMA: JsonSchema = {
  type: "object",
  required: ["id", "type", "createdAt", "organizationId", "data"],
  properties: {
    id: {
      type: "string",
      pattern: "^evt_",
      description:
        "Identificador del evento. Es el mismo en cada reintento: usalo para no procesar dos veces lo mismo.",
    },
    type: { type: "string", description: "Tipo del catálogo, con su versión." },
    createdAt: {
      type: "string",
      format: "date-time",
      description: "Cuándo ocurrió el hecho en el kernel.",
    },
    organizationId: {
      type: "string",
      description:
        "Organización (dentro del alcance de la app) a la que se refiere el evento.",
    },
    data: { type: "object" },
  },
};

export type PublicEnvelope = {
  id: string;
  type: string;
  createdAt: string;
  organizationId: string;
  data: Record<string, unknown>;
};

export const EXAMPLE_EVENT_ID = "evt_cm1exampleevent000000000";
export const EXAMPLE_CREATED_AT = "2026-10-02T21:15:04.000Z";

/** The full example body of a type, exactly as it would be POSTed. */
export function exampleEnvelope(definition: EventDefinition): PublicEnvelope {
  return {
    id: EXAMPLE_EVENT_ID,
    type: definition.type,
    createdAt: EXAMPLE_CREATED_AT,
    organizationId: ORG,
    data: definition.example,
  };
}

/** Body of `GET /events/catalog`. */
export function catalogDocument() {
  return {
    version: 1,
    signature: {
      algorithm: "HMAC-SHA256",
      signedPayload: "<MiRotaract-Webhook-Timestamp>.<cuerpo crudo>",
      headers: {
        id: "MiRotaract-Webhook-Id",
        timestamp: "MiRotaract-Webhook-Timestamp",
        signature: "MiRotaract-Signature",
      },
      toleranceSec: 300,
    },
    envelope: ENVELOPE_SCHEMA,
    events: EVENT_CATALOG.map((definition) => ({
      type: definition.type,
      name: definition.name,
      version: definition.version,
      title: definition.title,
      description: definition.description,
      scope: definition.scope,
      schema: definition.schema,
      example: exampleEnvelope(definition),
    })),
  };
}
